\]
\[
\begin{array}{c|cc}
&1495&\text{divided by }573\\
\cline{2-3}
&\downarrow&\\
573&2&\text{times}\\
&\downarrow&\\
&349&\text{remainder}
\end{array}
\]
\[
\begin{array}{c|cc}
&573&\text{divided by }349\\
\cline{2-3}
&\downarrow&\\
349&1&\text{times}\\
&\downarrow&\\
&224&\text{remainder}
\end{array}
\]
\[
\begin{array}{c|cc}
&349&\text{divided by }224\\
\cline{2-3}
&\downarrow&\\
224&1&\text{times}\\
&\downarrow&\\
&125&\text{remainder}
\end{array}
\]
\[
\begin{array}{c|cc}
&224&\text{divided by }125\\
\cline{2-3}
&\downarrow&\\
125&1&\text{times}\\
&\downarrow&\\
&99&\text{remainder}
\end{array}
\]
\[
\begin{array}{c|cc}
&125&\text{divided by }99\\
\cline{2-3}
&\downarrow&\\
99&1&\text{times}\\
&\downarrow&\\
&26&\text{remainder}
\end{array}
\]
\[
\begin{array}{c|cc}
&99&\text{divided by }26\\
\cline{2-3}
&\downarrow&\\
26&3&\text{times}\\
&\downarrow&\\
&21&\text{remainder}
\end{array}
\]
\[
\begin{array}{c|cc}
&26&\text{divided by }21\\
\cline{2-3}
